package com.clapfind.app;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.hardware.camera2.*;import android.media.*;import android.os.*;
public class ListeningService extends Service {
 volatile boolean listening=false;Thread worker;AudioRecord rec;ToneGenerator tone;CameraManager cam;String camId;Handler h=new Handler(Looper.getMainLooper());boolean alarm=false;long last=0;
 public void onCreate(){super.onCreate();tone=new ToneGenerator(AudioManager.STREAM_ALARM,100);cam=(CameraManager)getSystemService(CAMERA_SERVICE);try{for(String id:cam.getCameraIdList()){Boolean f=cam.getCameraCharacteristics(id).get(CameraCharacteristics.FLASH_INFO_AVAILABLE);if(Boolean.TRUE.equals(f)){camId=id;break;}}}catch(Exception e){}if(Build.VERSION.SDK_INT>=26)((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel("cf","ClapFind",NotificationManager.IMPORTANCE_LOW));}
 public int onStartCommand(Intent in,int flags,int id){String a=in==null?"START":in.getAction();if("SILENCE".equals(a)){silence();return START_STICKY;}if("STOP".equals(a)){silence();listening=false;try{if(rec!=null)rec.stop();}catch(Exception e){}stopForeground(true);stopSelf();return START_NOT_STICKY;}Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"cf"):new Notification.Builder(this);Notification n=b.setContentTitle("ClapFind is ON").setContentText("Clap or whistle to find your phone").setSmallIcon(android.R.drawable.ic_lock_silent_mode_off).build();try{if(Build.VERSION.SDK_INT>=29)startForeground(1,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_MICROPHONE|ServiceInfo.FOREGROUND_SERVICE_TYPE_CAMERA);else startForeground(1,n);}catch(Exception e){stopSelf();return START_NOT_STICKY;}if(!listening){listening=true;worker=new Thread(this::listen);worker.start();}return START_STICKY;}
 void listen(){int rate=16000,min=AudioRecord.getMinBufferSize(rate,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT);try{rec=new AudioRecord(MediaRecorder.AudioSource.VOICE_RECOGNITION,rate,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT,Math.max(min,4096));rec.startRecording();short[] b=new short[1024];double old=0;int whistleFrames=0;while(listening){int n=rec.read(b,0,b.length);if(n<1)continue;double sum=0;int crossings=0;short prev=b[0];for(int i=0;i<n;i++){double x=b[i]/32768.0;sum+=x*x;if((b[i]>=0&&prev<0)||(b[i]<0&&prev>=0))crossings++;prev=b[i];}double rms=Math.sqrt(sum/n),zcr=(double)crossings/n;boolean clap=rms>0.20&&old<rms*0.45;boolean whistleTone=rms>0.035&&zcr>0.055&&zcr<0.42;whistleFrames=whistleTone?whistleFrames+1:0;if(clap||whistleFrames>=3)ring();old=rms;}}catch(Exception e){}finally{try{if(rec!=null)rec.release();}catch(Exception e){}rec=null;}}
 synchronized void ring(){if(alarm||System.currentTimeMillis()-last<4000)return;last=System.currentTimeMillis();alarm=true;sendBroadcast(new Intent("com.clapfind.ALERT").setPackage(getPackageName()));h.post(()->{try{tone.startTone(ToneGenerator.TONE_CDMA_ALERT_CALL_GUARD,5000);}catch(Exception e){}try{Vibrator v=(Vibrator)getSystemService(VIBRATOR_SERVICE);if(v!=null)v.vibrate(new long[]{0,300,150,300,150,600},-1);}catch(Exception e){}if(camId!=null){for(int j=0;j<8;j++){final boolean on=j%2==0;h.postDelayed(()->{try{if(alarm)cam.setTorchMode(camId,on);}catch(Exception e){}},j*250L);}}});}
 void silence(){alarm=false;try{tone.stopTone();}catch(Exception e){}try{Vibrator v=(Vibrator)getSystemService(VIBRATOR_SERVICE);if(v!=null)v.cancel();}catch(Exception e){}try{if(camId!=null)cam.setTorchMode(camId,false);}catch(Exception e){}sendBroadcast(new Intent("com.clapfind.SILENCED").setPackage(getPackageName()));}
 public void onDestroy(){listening=false;silence();try{if(rec!=null)rec.stop();}catch(Exception e){}try{tone.release();}catch(Exception e){}super.onDestroy();}public IBinder onBind(Intent i){return null;}
}